7	import type {
8	  AgentProtocol,
9	  AgentSend,
10	  AgentEvent,
11	  Unsubscribe,
12	} from './types.js';
13	
14	/**
15	 * AgentSession is a wrapper around AgentProtocol that provides a more
16	 * convenient API for consuming agent activity as an AsyncIterable.
17	 */
18	export class AgentSession implements AgentProtocol {
19	  private _protocol: AgentProtocol;
20	
21	  constructor(protocol: AgentProtocol) {
22	    this._protocol = protocol;
23	  }
24	
25	  async send(payload: AgentSend): Promise<{ streamId: string | null }> {
26	    return this._protocol.send(payload);
27	  }
28	
29	  subscribe(callback: (event: AgentEvent) => void): Unsubscribe {
30	    return this._protocol.subscribe(callback);
31	  }
32	
33	  async abort(): Promise<void> {
34	    return this._protocol.abort();
35	  }
36	
37	  get events(): AgentEvent[] {
38	    return this._protocol.events;
39	  }
40	
41	  /**
42	   * Sends a payload to the agent and returns an AsyncIterable that yields
43	   * events for the resulting stream.
44	   *
45	   * @param payload The payload to send to the agent.
46	   */
47	  async *sendStream(payload: AgentSend): AsyncIterable<AgentEvent> {
48	    const result = await this._protocol.send(payload);
49	    const streamId = result.streamId;
50	
51	    if (streamId === null) {
52	      return;
53	    }
54	
55	    yield* this.stream({ streamId });
56	  }
57	
58	  /**
59	   * Returns an AsyncIterable that yields events from the agent session,
60	   * optionally replaying events from history or reattaching to an existing stream.
61	   *
62	   * @param options Options for replaying or reattaching to the event stream.
63	   */
64	  async *stream(
65	    options: {
66	      eventId?: string;
67	      streamId?: string;
68	    } = {},
69	  ): AsyncIterable<AgentEvent> {
70	    let resolve: (() => void) | undefined;
71	    let next = new Promise<void>((res) => {
72	      resolve = res;
73	    });
74	
75	    let eventQueue: AgentEvent[] = [];
76	    const earlyEvents: AgentEvent[] = [];
77	    let done = false;
78	    let trackedStreamId = options.streamId;
79	    let started = false;
80	
81	    // 1. Subscribe early to avoid missing any events that occur during replay setup
82	    const unsubscribe = this._protocol.subscribe((event) => {
83	      if (done) return;
84	
85	      if (!started) {
86	        earlyEvents.push(event);
87	        return;
88	      }
89	
90	      if (trackedStreamId && event.streamId !== trackedStreamId) return;
91	
92	      // If we don't have a tracked stream yet, the first agent_start we see becomes it.
93	      if (!trackedStreamId && event.type === 'agent_start') {
94	        trackedStreamId = event.streamId ?? undefined;
95	      }
96	
97	      // If we still don't have a tracked stream and we aren't replaying everything (eventId), ignore.
98	      if (!trackedStreamId && !options.eventId) return;
99	
100	      eventQueue.push(event);
101	      if (
102	        event.type === 'agent_end' &&
103	        event.streamId === (trackedStreamId ?? null)
104	      ) {
105	        done = true;
106	      }
107	
108	      const currentResolve = resolve;
109	      next = new Promise<void>((r) => {
110	        resolve = r;
111	      });
112	      currentResolve?.();
113	    });
114	
115	    try {
116	      const currentEvents = this._protocol.events;
117	      let replayStartIndex = -1;
118	
119	      if (options.eventId) {
120	        const index = currentEvents.findIndex((e) => e.id === options.eventId);
121	        if (index !== -1) {
122	          replayStartIndex = index + 1;
123	        }
124	      } else if (options.streamId) {
125	        const index = currentEvents.findIndex(
126	          (e) => e.type === 'agent_start' && e.streamId === options.streamId,
127	        );
128	        if (index !== -1) {
129	          replayStartIndex = index;
130	        }
131	      }
132	
133	      if (replayStartIndex !== -1) {
134	        for (let i = replayStartIndex; i < currentEvents.length; i++) {
135	          const event = currentEvents[i];
136	          if (options.streamId && event.streamId !== options.streamId) continue;
137	
138	          eventQueue.push(event);
139	          if (event.type === 'agent_start' && !trackedStreamId) {
140	            trackedStreamId = event.streamId ?? undefined;
141	          }
142	          if (
143	            event.type === 'agent_end' &&
144	            event.streamId === (trackedStreamId ?? null)
145	          ) {
146	            done = true;
147	            break;
148	          }
149	        }
150	      }
151	
152	      if (!done && !trackedStreamId) {
153	        // Find active stream in history
154	        const activeStarts = currentEvents.filter(
155	          (e) => e.type === 'agent_start',
156	        );
157	        for (let i = activeStarts.length - 1; i >= 0; i--) {
158	          const start = activeStarts[i];
159	          if (
160	            !currentEvents.some(
161	              (e) => e.type === 'agent_end' && e.streamId === start.streamId,
162	            )
163	          ) {
164	            trackedStreamId = start.streamId ?? undefined;
165	            break;
166	          }
167	        }
168	      }
169	
170	      // If we replayed to the end and no stream is active, and we were specifically
171	      // replaying from an eventId (or we've already finished the stream we were looking for), we are done.
172	      if (!done && !trackedStreamId && options.eventId) {
173	        done = true;
174	      }
175	
176	      started = true;
177	
178	      // Process events that arrived while we were replaying
179	      for (const event of earlyEvents) {
180	        if (done) break;
181	        if (trackedStreamId && event.streamId !== trackedStreamId) continue;
182	        if (!trackedStreamId && event.type === 'agent_start') {
183	          trackedStreamId = event.streamId ?? undefined;
184	        }
185	        if (!trackedStreamId && !options.eventId) continue;
186	
187	        eventQueue.push(event);
188	        if (
189	          event.type === 'agent_end' &&
190	          event.streamId === (trackedStreamId ?? null)
191	        ) {
192	          done = true;
193	        }
194	      }
195	
196	      while (true) {
197	        if (eventQueue.length > 0) {
198	          const eventsToYield = eventQueue;
199	          eventQueue = [];
200	          for (const event of eventsToYield) {
201	            yield event;
202	          }
203	        }
204	
205	        if (done) break;
206	        await next;
207	      }
208	    } finally {
209	      unsubscribe();
210	    }
211	  }
212	}
